userDefinedLinkHintCss:
/* Nord palette
   nord0 #2e3440  nord1 #3b4252  nord2 #434c5e  nord3 #4c566a
   nord4 #d8dee9  nord5 #e5e9f0  nord6 #eceff4
   nord7 #8fbcbb  nord8 #88c0d0  nord9 #81a1c1  nord10 #5e81ac
   nord11 #bf616a nord12 #d08770 nord13 #ebcb8b nord14 #a3be8c nord15 #b48ead */

/* Link hints: dark nord0 boxes framed in the window border's nord9, so they
   read on light and dark pages alike. Snow-white letters; letters already
   typed turn nord11 red. Contrast on #2e3440: white 11:1, red 3.3:1. */
div > .vimiumHintMarker {
  padding: 2px 5px;
  background: #2e3440;
  border: 1px solid #81a1c1;
  border-radius: 2px;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.45);
}

div > .vimiumHintMarker span {
  font-size: 16px;
  font-weight: bold;
  text-shadow: none;
  color: #eceff4;
}

div > .vimiumHintMarker > .matchingCharacter {
  color: #bf616a;
}

/* Vomnibar (Vimium 2.x class names). 2px white border; background and
   font as WezTerm (nord, RobotoMono Nerd Font). */
:root {
  --vimium-background-color: #2e3440;
  --vimium-background-text-color: #d8dee9;
  --vimium-foreground-color: #3b4252;
  --vimium-foreground-text-color: #eceff4;
  --vimium-link-color: #88c0d0;
}

#vomnibar {
  background-color: #2e3440;
  color: #d8dee9;
  border: 2px solid #eceff4;
  font-family: "RobotoMono Nerd Font", "Roboto Mono", monospace;
  border-radius: 0;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.5);
  width: 70%;
  top: 0;
  left: 15%;
}

#vomnibar-search-area {
  padding: 0;
  border-radius: 0;
  border-bottom: 2px solid #eceff4;
}

#vomnibar input {
  height: 56px;
  padding: 8px 14px;
  font-family: "RobotoMono Nerd Font", "Roboto Mono", monospace;
  font-size: 20px;
  background-color: #2e3440;
  color: #eceff4;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

#vomnibar input::selection {
  color: #eceff4;
  background-color: #5e81ac;
}

#vomnibar ul {
  border-radius: 0;
}

#vomnibar li {
  color: #d8dee9;
  font-family: "RobotoMono Nerd Font", "Roboto Mono", monospace;
  border-bottom: 1px solid #3b4252;
}

/* One line per half, so every row is the same height; long titles and URLs
   end in an ellipsis instead of wrapping */
#vomnibar li .top-half,
#vomnibar li .bottom-half {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

#vomnibar li:hover,
#vomnibar li.selected {
  background-color: rgba(94, 129, 172, 0.35);
}

#vomnibar li .source {
  color: #81a1c1;
}

#vomnibar li em,
#vomnibar li .title {
  color: #eceff4;
}

#vomnibar li .url {
  color: #d8dee9;
  opacity: 0.6;
}

#vomnibar li .match,
#vomnibar li em .match,
#vomnibar li .title .match {
  color: #88c0d0;
  font-weight: bold;
}

/* HUD / find mode */
#hud-container {
  background-color: #2e3440;
  color: #eceff4;
  border: 2px solid #eceff4;
  font-family: "RobotoMono Nerd Font", "Roboto Mono", monospace;
  border-radius: 0;
  box-shadow: none;
}

#hud {
  background-color: #2e3440;
  border: none;
  border-radius: 0;
}

span#hud-find-input {
  color: #eceff4;
}

span#hud-match-count {
  color: #81a1c1;
}
